{"ok": true, "path": "jiayan-tests/ui.test.js", "content": "1: // UI 功能测试：通过微信开发者工具 automator 驱动真实模拟器
2: const automator = require('miniprogram-automator');
3: 
4: // 兼容补丁：新版开发者工具不返回 SDK 版本号，automator 0.12 的 checkVersion 会崩溃，跳过它
5: try {
6:   const MP = require('miniprogram-automator/out/MiniProgram');
7:   const cls = MP.default || MP;
8:   if (cls && cls.prototype) cls.prototype.checkVersion = async () => {};
9: } catch (e) {}
10: 
11: const CLI = '/Applications/wechatwebdevtools.app/Contents/MacOS/cli';
12: const PROJECT = '/Users/ict/Documents/oh-my-home/jiayan-miniprogram';
13: 
14: let passed = 0, failed = 0;
15: function ok(name, cond) {
16:   if (cond) { passed++; console.log('  ✔ ' + name); }
17:   else { failed++; console.log('  ✘ ' + name); }
18: }
19: const sleep = ms => new Promise(r => setTimeout(r, ms));
20: 
21: (async () => {
22:   console.log('连接开发者工具自动化端口…');
23:   let mini;
24:   try {
25:     mini = await automator.connect({ wsEndpoint: 'ws://localhost:9420' });
26:   } catch (e) {
27:     console.log('直连失败，尝试 launch…');
28:     mini = await automator.launch({ cliPath: CLI, projectPath: PROJECT, timeout: 120000 });
29:   }
30:   try {
31:     // ---------- 首页 ----------
32:     let page = await mini.reLaunch('/pages/home/home');
33:     await sleep(800);
34:     ok('首页加载，路径正确', page.path === 'pages/home/home');
35:     let el = await page.$('.title, .pad');
36:     ok('首页渲染出内容区', !!el);
37:     const heading = await page.xpath ? null : null;
38:     const texts = await page.$$('view');
39:     ok('首页渲染出「晚上吃点什么？」', (await Promise.all(texts.slice(0, 40).map(t => t.text().catch(() => '')))).join('').includes('晚上吃点什么'));
40: 
41:     // 换一个：推荐菜名应变化
42:     const recName1 = (await page.data()).rec.name;
43:     const btns = await page.$$('view.btn');
44:     let switchBtn = null;
45:     for (const b of btns) { if ((await b.text()).includes('换一个')) { switchBtn = b; break; } }
46:     await switchBtn.tap();
47:     await sleep(400);
48:     const recName2 = (await page.data()).rec.name;
49:     ok('「换一个」切换今日推荐 (' + recName1 + ' → ' + recName2 + ')', recName1 !== recName2);
50: 
51:     // ---------- 菜谱库筛选 ----------
52:     page = await mini.reLaunch('/pages/library/library');
53:     await sleep(600);
54:     const allCount = (await page.data()).list.length;
55:     const chips = await page.$$('view.chip');
56:     for (const c of chips) { if ((await c.text()).startsWith('想吃')) { await c.tap(); break; } }
57:     await sleep(400);
58:     // 筛选后重新获取当前页面引用，避免访问已失效的页面节点
59:     page = await mini.currentPage();
60:     const wantList = (await page.data()).list;
61:     ok('菜谱库「想吃」筛选生效 (' + allCount + ' → ' + wantList.length + ' 道)', wantList.length < allCount && wantList.every(d => d.status === '想吃'));
62: 
63:     // ---------- 菜品详情评分 ----------
64:     page = await mini.reLaunch('/pages/dish/dish?name=红烧肉');
65:     await sleep(600);
66:     ok('详情页显示红烧肉与热量', (await page.data()).d.kcal === 520);
67:     const stars = await page.$$('text.star');
68:     await stars[2].tap(); // 点第 3 颗星
69:     await sleep(300);
70:     ok('点星评分生效 (rating=3)', (await page.data()).rating === 3);
71: 
72:     // ---------- 客人点菜 ----------
73:     page = await mini.reLaunch('/pages/guest/guest');
74:     await sleep(600);
75:     const before = (await page.data()).cartCount;
76:     const menu = (await page.data()).menu;
77:     const target = menu.find(m => !m.inCart);
78:     const toggles = await page.$$('view');
79:     for (const t of toggles) {
80:       const txt = await t.text().catch(() => '');
81:       if (txt === '＋ 点') { await t.tap(); break; }
82:     }
83:     await sleep(400);
84:     const after = (await page.data()).cartCount;
85:     ok('客人加菜 (' + before + ' → ' + after + ' 道)', after === before + 1);
86: 
87:     // ---------- 转盘 ----------
88:     page = await mini.reLaunch('/pages/wheel/wheel');
89:     await sleep(600);
90:     // 触发方式:点转盘中心的「转 / SPIN」圆钮(取最小命中节点,失败则直接调页面方法)
91:     const spinViews = await page.$$('view');
92:     let hub = null;
93:     for (const b of spinViews) {
94:       const t = await b.text().catch(() => '');
95:       if (t.includes('SPIN')) hub = b;
96:     }
97:     if (hub) await hub.tap();
98:     await sleep(200);
99:     if (!(await page.data()).spinning) await page.callMethod('spin');
100:     await sleep(100);
101:     ok('转盘开始旋转 (spinning=true)', (await page.data()).spinning === true);
102:     await sleep(2800);
103:     const wd = await page.data();
104:     ok('转盘停下并给出结果 (' + wd.result + ')', wd.spinning === false && wd.result !== '· · ·');
105: 
106:     // ---------- 滑卡 ----------
107:     page = await mini.reLaunch('/pages/swipe/swipe');
108:     await sleep(600);
109:     const likedBefore = (await page.data()).liked.length;
110:     const curName = (await page.data()).cur.name;
111:     const circles = await page.$$('view');
112:     for (const c of circles) { if ((await c.text().catch(() => '')) === '想') { await c.tap(); break; } }
113:     await sleep(500);
114:     const sd = await page.data();
115:     ok('滑卡「想吃」进清单并切下一张', sd.liked.length >= likedBefore && sd.cur.name !== curName);
116: 
117:     // ---------- 心情筛选 ----------
118:     page = await mini.reLaunch('/pages/mood/mood');
119:     await sleep(600);
120:     const moodChips = await page.$$('view.chip');
121:     for (const c of moodChips) { if ((await c.text()) === '想吃辣') { await c.tap(); break; } }
122:     await sleep(400);
123:     const md = await page.data();
124:     ok('心情切到「想吃辣」，推荐列表更新', md.mood === '想吃辣' && md.list.some(d => d.name === '麻婆豆腐'));
125: 
126:     // ---------- 今天就这样 ----------
127:     page = await mini.reLaunch('/pages/today/today');
128:     await sleep(600);
129:     const td = await page.data();
130:     ok('定餐页合计热量 = 各菜之和', td.totalKcal === td.list.reduce((a, d) => a + d.kcal, 0) && td.totalKcal > 0);
131: 
132:   } catch (e) {
133:     failed++;
134:     console.error('  ✘ 用例执行异常: ' + (e && e.stack || e));
135:   } finally {
136:     console.log('\nUI 测试结果: ' + passed + ' 通过, ' + failed + ' 失败');
137:     try { await mini.disconnect(); } catch (e) {}
138:     process.exit(failed ? 1 : 0);
139:   }
140: })().catch(e => { console.error('UI 测试运行失败:', e.message); process.exit(2); });", "total_lines": 140}
